const LEAD = [[0,"REST",0,1],[16,"A",0,1],[48,"A",0,1],[80,"A",0,1],[112,"REST",0,1],[144,"REST",0,1],[176,"REST",0,1],[272,"A",0,1],[304,"A",0,1],[336,"A",0,2]]
